    Assert.assertEquals(counterOrig.generateUniqueId(), counter.generateUniqueId());
    Assert.assertEquals(counterOrig.generateUniqueId(), counter.generateUniqueId());
    counterOrig.endUniqueIdSection();
    counter.endUniqueIdSection();
    Assert.assertEquals(counterOrig.generateUniqueId(), counter.generateUniqueId());
    Assert.assertEquals(counterOrig.generateUniqueId(), counter.generateUniqueId());
    Assert.assertEquals(counterOrig.generateUniqueId(), counter.generateUniqueId());
    Assert.assertEquals(counterOrig.generateUniqueId(), counter.generateUniqueId());
}

